from typing import List

class Solution:
    def sumSubseqWidths(self, nums: List[int]) -> int:
        MOD = 1_000_000_007
        nums.sort()
        n = len(nums)
        pow2 = [1] * n
        for i in range(1, n):
            pow2[i] = (pow2[i - 1] * 2) % MOD

        ans = 0
        for i in range(n):
            ans = (ans + nums[i] * (pow2[i] - pow2[n - 1 - i])) % MOD
        return (ans + MOD) % MOD

class Solution {
public:
    int sumSubseqWidths(vector<int>& nums) {
        long long MOD = 1000000007;
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<long long> pow2(n, 1);
        for (int i = 1; i < n; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;
        long long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + nums[i] * (pow2[i] - pow2[n - 1 - i])) % MOD;
        }
        return (ans + MOD) % MOD;
    }
};

class Solution {
    public int sumSubseqWidths(int[] nums) {
        long MOD = 1_000_000_007L;
        Arrays.sort(nums);
        int n = nums.length;
        long[] pow2 = new long[n];
        pow2[0] = 1;
        for (int i = 1; i < n; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;
        long ans = 0;
        for (int i = 0; i < n; i++) {
            ans = (ans + (long) nums[i] * (pow2[i] - pow2[n - 1 - i])) % MOD;
        }
        return (int) ((ans + MOD) % MOD);
    }
}

var sumSubseqWidths = function(nums) {
    const MOD = 1000000007n;
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const pow2 = new Array(n).fill(1n);
    for (let i = 1; i < n; i++) pow2[i] = (pow2[i - 1] * 2n) % MOD;
    let ans = 0n;
    for (let i = 0; i < n; i++) {
        const val = BigInt(nums[i]);
        ans = (ans + val * (pow2[i] - pow2[n - 1 - i])) % MOD;
    }
    return Number((ans + MOD) % MOD);
};
